const latestReview=computed(()=>reviews.value[0]);
const statCards=computed(()=>stats.value?[{label:'已平仓',value:stats.value.closedTrades},{label:'胜率',value:stats.value.winRate+'%'},{label:'平均收益',value:stats.value.averageReturn+'%'},{label:'盈亏比',value:stats.value.profitLossRatio},{label:'已实现盈亏',value:money(stats.value.realizedProfit)},{label:'未实现盈亏',value:money(stats.value.unrealizedProfit)},{label:'总费用',value:money(stats.value.totalFees)}]:[]);

async function loadAlerts(){alertRules.value=(await api.listAlertRules()).data;alertEvents.value=(await api.listAlertEvents()).data;marketAlertRules.value=(await api.listMarketAlertRules()).data;marketAlertEvents.value=(await api.listMarketAlertEvents()).data;}
async function loadTab(){if(tab.value==='review')reviews.value=(await api.listReviews()).data;if(tab.value==='trades'){trades.value=(await api.listTrades()).data;await loadAlerts();}if(tab.value==='plans')plans.value=(await api.listPlans()).data;if(tab.value==='alerts')await loadAlerts();if(tab.value==='mistakes')mistakes.value=(await api.listMistakes()).data;if(tab.value==='stats')stats.value=(await api.getTradingStats()).data;}
function persistNotes(){localStorage.setItem('trading-thought-notes',JSON.stringify(notes.value));}
function newNote(){editingNoteId.value=undefined;Object.assign(noteForm,{id:'',tradeDate:today(),scope:'MARKET',stockCode:'',stockName:'',title:'',content:'',tags:'',updatedAt:''});noteVisible.value=true;}
function editNote(note:ThoughtNote){editingNoteId.value=note.id;Object.assign(noteForm,note);noteVisible.value=true;}
function saveNote(){if(!noteForm.content.trim()){ElMessage.warning('请先写下思考内容');return;}const item={...noteForm,id:editingNoteId.value||crypto.randomUUID(),updatedAt:new Date().toISOString()};const index=notes.value.findIndex(note=>note.id===item.id);if(index>=0)notes.value.splice(index,1,item);else notes.value.unshift(item);persistNotes();noteVisible.value=false;ElMessage.success('思考记录已保存');}
async function removeNote(id:string){await confirmDelete();notes.value=notes.value.filter(note=>note.id!==id);persistNotes();}
async function refresh(){refreshing.value=true;try{const result=(await api.refreshMarket(reviewForm.tradeDate,reviewForm.snapshotType)).data;ElMessage[result.fresh?'success':'warning'](result.message);await loadTab();analyticsRefreshKey.value++;}finally{refreshing.value=false;}}
async function generateTradingReport(){const reference=latestReview.value?.tradeDate||reviewForm.tradeDate;const report=(await generateReport('TRADING_DAILY',reference)).data;ElMessage.success('交易研究日报已生成：'+report.title);}
function editReview(item:DailyReview){editingId.value=item.id;Object.assign(reviewForm,item);reviewVisible.value=true;}async function submitReview(){await api.saveReview(reviewForm,editingId.value);finish(reviewVisible);await loadTab();}async function deleteReviewRow(id:number){await confirmDelete();await api.removeReview(id);await loadTab();}
function newTrade(){editingId.value=undefined;Object.assign(tradeForm,blankTrade());tradeVisible.value=true;void loadAlerts();}function editTrade(item:TradeLog){editingId.value=item.id;Object.assign(tradeForm,blankTrade(),item);tradeVisible.value=true;void loadAlerts();}async function submitTrade(){await api.saveTrade(tradeForm,editingId.value);finish(tradeVisible);await loadTab();}async function deleteTradeRow(id:number){await confirmDelete();await api.removeTrade(id);await loadTab();}async function openTrade(item:TradeLog){tradeDetail.value=(await api.getTrade(item.id)).data;detailVisible.value=true;}async function submitExecution(){if(!tradeDetail.value)return;await api.addExecution(tradeDetail.value.trade.id,executionForm);tradeDetail.value=(await api.getTrade(tradeDetail.value.trade.id)).data;await loadTab();}async function deleteExecutionRow(id:number){if(!tradeDetail.value)return;await confirmDelete();await api.removeExecution(tradeDetail.value.trade.id,id);tradeDetail.value=(await api.getTrade(tradeDetail.value.trade.id)).data;await loadTab();}
function newPlan(){editingId.value=undefined;Object.assign(planForm,{tradeDate:today(),marketPremise:'',targetPosition:0,watchStocks:'',plannedTrades:'',riskControls:'',reminderIds:'',reportNote:'',status:'DRAFT'});planVisible.value=true;}function editPlan(item:NextPlan){editingId.value=item.id;Object.assign(planForm,item);planVisible.value=true;}async function submitPlan(){await api.savePlan(planForm,editingId.value);finish(planVisible);await loadTab();}async function deletePlanRow(id:number){await confirmDelete();await api.removePlan(id);await loadTab();}
function newAlertRule(){editingId.value=undefined;Object.assign(alertForm,{watchItemId:null,planId:null,stockCode:'',stockName:'',ruleType:'PRICE',direction:'ABOVE',thresholdValue:null,referencePosition:null,title:'',note:'',enabled:true,onceOnly:true,validFrom:'',validTo:''});alertVisible.value=true;}
function editAlertRule(item:TradingAlertRule){editingId.value=item.id;Object.assign(alertForm,item);alertVisible.value=true;}
async function submitAlertRule(){await api.saveAlertRule(alertForm,editingId.value);finish(alertVisible);await loadTab();}
async function toggleAlert(item:TradingAlertRule){await api.toggleAlertRule(item.id,item.enabled);await loadTab();}
async function deleteAlertRuleRow(id:number){await confirmDelete();await api.removeAlertRule(id);await loadTab();}
async function scanAlerts(){alertScanning.value=true;try{const result=(await api.scanAlertRules()).data;ElMessage.success(`扫描 ${result.checkedRules} 条，触发 ${result.triggeredEvents} 条，跳过 ${result.skippedRules} 条`);await loadTab();}finally{alertScanning.value=false;}}
function newMarketAlertRule(){editingId.value=undefined;Object.assign(marketAlertForm,{ruleType:'MARKET_METRIC',snapshotType:'ANY',metricKey:'BROKEN_BOARD_RATE',direction:'ABOVE',thresholdValue:null,sectorName:'',sectorLevel:null,title:'',note:'',enabled:true,onceOnly:false,validFrom:'',validTo:''});marketAlertVisible.value=true;}
function editMarketAlertRule(item:TradingMarketAlertRule){editingId.value=item.id;Object.assign(marketAlertForm,item);marketAlertVisible.value=true;}
async function submitMarketAlertRule(){await api.saveMarketAlertRule(marketAlertForm,editingId.value);finish(marketAlertVisible);await loadTab();}
async function toggleMarketAlert(item:TradingMarketAlertRule){await api.toggleMarketAlertRule(item.id,item.enabled);await loadTab();}
async function deleteMarketAlertRuleRow(id:number){await confirmDelete();await api.removeMarketAlertRule(id);await loadTab();}
async function scanMarketAlerts(){marketAlertScanning.value=true;try{const result=(await api.scanMarketAlertRules()).data;ElMessage.success(`市场扫描 ${result.checkedRules} 条，触发 ${result.triggeredEvents} 条，跳过 ${result.skippedRules} 条`);await loadTab();}finally{marketAlertScanning.value=false;}}
function newMistake(){editingId.value=undefined;Object.assign(mistakeForm,{occurredDate:today(),category:'',title:'',description:'',rootCause:'',correction:'',status:'OPEN',repeatCount:1});mistakeVisible.value=true;}function editMistake(item:TradingMistake){editingId.value=item.id;Object.assign(mistakeForm,item);mistakeVisible.value=true;}async function submitMistake(){await api.saveMistake(mistakeForm,editingId.value);finish(mistakeVisible);await loadTab();}async function deleteMistakeRow(id:number){await confirmDelete();await api.removeMistake(id);await loadTab();}
function finish(visible:{value:boolean}){visible.value=false;editingId.value=undefined;localStorage.removeItem('trading-review-draft');ElMessage.success('保存成功');}
const confirmDelete=()=>ElMessageBox.confirm('删除后不可恢复，是否继续？','确认删除',{type:'warning'});
const planStatus=(v:string)=>({DRAFT:'草稿',ACTIVE:'执行中',COMPLETED:'已完成',CANCELLED:'已取消'}[v]||v);
const alertRuleType=(v:string)=>({PRICE:'价格',CHANGE_PERCENT:'涨跌幅',STOP_LOSS:'止损',TAKE_PROFIT:'止盈',POSITION_DEVIATION:'仓位偏差'}[v]||v);
const alertDirection=(v:string)=>v==='BELOW'?'≤':'≥';
const alertStatus=(v:string)=>({MONITORING:'监控中',TRIGGERED:'已触发',DISABLED:'已停用',NO_QUOTE:'缺行情'}[v]||v);
const alertStatusType=(v:string)=>v==='TRIGGERED'?'danger':v==='NO_QUOTE'?'warning':v==='DISABLED'?'info':'success';
const notificationStatus=(v:string)=>({SENT:'已发送',NO_CHANNEL:'无通道',FAILED:'发送失败'}[v]||v);
const marketRuleType=(v:string)=>v==='SECTOR_METRIC'?'板块':'市场';
const marketMetricName=(v:string)=>({SENTIMENT_SCORE:'情绪评分',BROKEN_BOARD_RATE:'炸板率',LIMIT_DOWN_COUNT:'跌停数',LIMIT_UP_COUNT:'涨停数',RISING_COUNT:'上涨家数',FALLING_COUNT:'下跌家数',TURNOVER_CHANGE:'成交额变化',MAX_STREAK:'连板高度',MARKET_MEDIAN_CHANGE:'市场涨幅中位数',CHANGE:'板块涨跌幅',TURNOVER:'板块成交额',RISING:'板块上涨家数',FALLING:'板块下跌家数'}[v]||v);
const marketAlertRuleText=(row:TradingMarketAlertRule)=>marketRuleType(row.ruleType)+' '+(row.sectorName||'')+' '+marketMetricName(row.metricKey)+' '+alertDirection(row.direction)+' '+row.thresholdValue+(['BROKEN_BOARD_RATE','TURNOVER_CHANGE','MARKET_MEDIAN_CHANGE','CHANGE'].includes(row.metricKey)?'%':'');
const marketAlertEventText=(row:TradingMarketAlertEvent)=>row.tradeDate+' '+row.snapshotType+' '+(row.sectorName||'市场')+' '+marketMetricName(row.metricKey)+' 观察值 '+row.observedValue+'，阈值 '+row.thresholdValue;
const marketMetricOptions=[{label:'情绪评分',value:'SENTIMENT_SCORE'},{label:'炸板率',value:'BROKEN_BOARD_RATE'},{label:'跌停数',value:'LIMIT_DOWN_COUNT'},{label:'涨停数',value:'LIMIT_UP_COUNT'},{label:'上涨家数',value:'RISING_COUNT'},{label:'下跌家数',value:'FALLING_COUNT'},{label:'成交额变化',value:'TURNOVER_CHANGE'},{label:'连板高度',value:'MAX_STREAK'},{label:'市场涨幅中位数',value:'MARKET_MEDIAN_CHANGE'},{label:'板块涨跌幅',value:'CHANGE'},{label:'板块成交额',value:'TURNOVER'},{label:'板块涨停数',value:'LIMIT_UP_COUNT'},{label:'板块上涨家数',value:'RISING'},{label:'板块下跌家数',value:'FALLING'}];
const alertRuleText=(row:TradingAlertRule)=>`${alertRuleType(row.ruleType)} ${alertDirection(row.direction)} ${row.thresholdValue}${row.ruleType==='CHANGE_PERCENT'||row.ruleType==='POSITION_DEVIATION'?'%':''}`;
const alertEventText=(row:TradingAlertEvent)=>`${row.stockName} 观察值 ${row.observedValue}，阈值 ${row.thresholdValue}，最新价 ${row.latestPrice??'-'}，涨跌幅 ${row.changePercent??'-'}%`;
const money=(v?:number)=>Number(v||0).toFixed(2);const percent=(v?:number)=>Number(v||0).toFixed(2)+'%';const completeness=(v:string)=>({COMPLETE:'完整',INCOMPLETE:'数据不完整',MANUAL:'手工录入'}[v]||v);const formatTime=(v?:string)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'-';const errorPercent=(count:number)=>Math.min(100,count/Math.max(...(stats.value?.frequentErrors.map(v=>v.count)||[1]))*100);
const dirty=computed(()=>reviewVisible.value||tradeVisible.value||planVisible.value||alertVisible.value||marketAlertVisible.value||mistakeVisible.value||noteVisible.value);
watch([reviewForm,tradeForm,planForm,alertForm,marketAlertForm,mistakeForm],()=>{if(dirty.value)localStorage.setItem('trading-review-draft',JSON.stringify({reviewForm,tradeForm,planForm,alertForm,marketAlertForm,mistakeForm}));},{deep:true});
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue='';}}
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);try{notes.value=JSON.parse(localStorage.getItem('trading-thought-notes')||'[]');}catch{notes.value=[];}const draft=localStorage.getItem('trading-review-draft');if(draft){try{const saved=JSON.parse(draft);Object.assign(reviewForm,saved.reviewForm||{});Object.assign(tradeForm,saved.tradeForm||{});Object.assign(planForm,saved.planForm||{});Object.assign(alertForm,saved.alertForm||{});Object.assign(marketAlertForm,saved.marketAlertForm||{});Object.assign(mistakeForm,saved.mistakeForm||{});ElMessage.info('已恢复上次未保存草稿');}catch{localStorage.removeItem('trading-review-draft');}}await loadTab();});onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload));
</script>

