@media(max-width:900px){.card-list{grid-template-columns:repeat(2,1fr)}.review-summary,.stats{grid-template-columns:repeat(2,1fr)}}
@media(max-width:600px){.hero{align-items:flex-start;flex-direction:column;gap:16px;padding:18px}.quick-links{width:100%;overflow-x:auto}.toolbar{align-items:stretch;flex-direction:column}.toolbar>div{display:grid;grid-template-columns:1fr 1fr}.card-list,.form-grid,.execution-form{grid-template-columns:1fr}.review-summary,.stats{grid-template-columns:repeat(2,1fr);gap:8px}.review-summary :deep(.el-card__body),.stats :deep(.el-card__body){padding:13px}.review-summary strong,.stats strong{font-size:19px}.metrics{grid-template-columns:repeat(2,1fr)}.error-row{grid-template-columns:90px 1fr}.trading-page :deep(.el-table){min-width:680px}.trading-page :deep(.el-card){overflow-x:auto}}
